.compact-table tbody td {
    border-color: rgba(75, 108, 158, 0.1);
    font-size: 0.82rem;
    padding: 0.66rem 0.42rem;
}

.ai-insight-panel {
    background: linear-gradient(135deg, #fff 0%, var(--school-primary-soft) 100%);
    border-color: rgba(75, 108, 158, 0.24);
    padding: 18px 20px;
}

.ai-insight-header {
    align-items: center;
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    justify-content: space-between;
    margin-bottom: 14px;
}

.ai-insight-badge {
    align-items: center;
    background: var(--school-primary);
    border-radius: 999px;
    color: #fff;
    display: inline-flex;
    font-size: 0.88rem;
    font-weight: 800;
    gap: 8px;
    padding: 8px 14px;
}

.ai-insight-list {
    display: grid;
    gap: 10px;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    list-style: none;
    margin: 0;
    padding: 0;
}

.ai-insight-list li {
    align-items: flex-start;
    background: rgba(255, 255, 255, 0.82);
    border: 1px solid var(--school-border);
    border-radius: 8px;
    color: var(--school-text);
    display: flex;
    font-size: 0.86rem;
    gap: 10px;
    line-height: 1.45;
    padding: 12px 14px;
}

.ai-insight-list li i {
    color: var(--school-primary);
    flex: 0 0 auto;
    font-size: 1rem;
    margin-top: 2px;
}

.ai-insight-list li strong {
    color: var(--school-primary-dark);
}

.ai-insight-grid {
    display: grid;
    gap: 12px;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.ai-insight-card {
    background: #f7f9fc;
    border: 1px solid var(--school-border);
    border-left-width: 4px;
    border-radius: 8px;
    padding: 14px;
}

.ai-insight-card h3 {
    color: var(--school-text);
    font-size: 0.9rem;
    font-weight: 800;
    margin: 0 0 8px;
}

.ai-insight-card p {
    color: var(--school-muted);
    font-size: 0.84rem;
    line-height: 1.45;
    margin: 0;
}

.ai-insight-card.danger {
    border-left-color: var(--school-danger);
}

.ai-insight-card.warning {
    border-left-color: var(--school-warning);
}

.ai-insight-card.success {
    border-left-color: var(--school-success);
}

.ai-insight-card.info {
    border-left-color: var(--school-primary);
}

.ai-insight-module {
    border-color: rgba(75, 108, 158, 0.28);
}

